WITH dedup AS (
  SELECT * FROM events WHERE event_name='purchase' QUALIFY ROW_NUMBER() OVER (PARTITION BY event_id ORDER BY ingested_at) = 1
), d AS (
  SELECT order_id FROM dedup GROUP BY order_id HAVING COUNT(*) > 1
)
SELECT e.order_id, e.event_id, e.user_id, u.is_internal, e.event_ts, e.ingested_at, e.revenue_cents, e.product_id
FROM dedup e JOIN d USING (order_id) JOIN users u USING (user_id)
ORDER BY e.order_id, e.event_ts LIMIT 20;
